"const fs = require('fs');
const path = require('path');

const projectRoot = 'c:\\Users\\lorik\\.gemini\\antigravity\\scratch\\anymd';
const srcMainJava = path.join(projectRoot, 'android', 'app', 'src', 'main', 'java');
const oldPkgPath = path.join(srcMainJava, 'net', 'artkitty', 'myblackbox');
const newPkgPath = path.join(srcMainJava, 'net', 'artkitty', 'anymd');

// Helper to recursively process directories and files
function processDir(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      processDir(fullPath);
    } else if (entry.isFile() && (entry.name.endsWith('.kt') || entry.name.endsWith('.java'))) {
      let content = fs.readFileSync(fullPath, 'utf8');
      if (content.includes('net.artkitty.myblackbox')) {
        console.log(`Updating package reference in: ${fullPath}`);
        content = content.split('net.artkitty.myblackbox').join('net.artkitty.anymd');
        fs.writeFileSync(fullPath, content, 'utf8');
      }
    }
  }
}

// 1. Process files in the old package directory first to update package declarations
if (fs.existsSync(oldPkgPath)) {
  processDir(oldPkgPath);

  // Ensure target directory exists parent-wise
  const newParent = path.dirname(newPkgPath);
  if (!fs.existsSync(newParent)) {
    fs.mkdirSync(newParent, { recursive: true });
  }

  // Move the directory
  console.log(`Renaming ${oldPkgPath} to ${newPkgPath}`);
  fs.renameSync(oldPkgPath, newPkgPath);
  console.log('Rename complete!');
} else {
  console.log('Old package path not found, already renamed or wrong path?');
}
